"""Enquiry pages: public UI. Mail transport remains disabled until configured."""
def build_enquiry_pages(g):
    shell=g['shell'];intro=g['intro'];image=g['image']
    sections=[('bookings','Event bookings','Ready to take your show on tour? Talk to Kings of Kings International about presenting your event, upcoming shows or including your act in a lineup.','Start an event enquiry'),('artists','Artist enquiries','Explore releasing your music through Kings of Kings Records, book an existing artist, or enquire specifically about booking Iley Dread.','Connect with the label'),('partners','Sponsorship & charities','Let’s work together for a cause. Tell us about your charity, sponsorship proposal or an opportunity to support the communities around the music.','Discuss a partnership'),('mailing-list','Stay in the vibration','Join the newsletter for upcoming events and Kings news. Eligible subscribers aged 18 or older receive an entry in the Upliftment giveaway when registration opens.','Join the mailing list'),('top-15','Kings of Kings Top 15 Chart','Coming soon. A new chart from Kings of Kings. Join the list to be among the first to know when it launches.','Notify me about the Top 15'),('contests','Contests & special promotions','Registration opens with special promotions. Discover the Upliftment album giveaway planned for January 5, 2027.','Explore the giveaway'),('general','General enquiries','Have a question or an idea? Send the Kings of Kings International team a message.','Contact the team')]
    body=intro('LET’S CONNECT','Let’s make<br><em>your soul move.</em>','Choose the conversation you want to start. Tell us what you have in mind and our team will follow up.')+'<section class="section enquiry-grid">'
    for ident,title,text,cta in sections:
        button=f'<a class="text-link" href="/contests/">{cta} ↗</a>' if ident=='contests' else f'<button class="text-link enquiry-open" data-enquiry="{ident}">{cta} ↗</button>'
        body+=f'<article id="{ident}"><h2>{title}</h2><p>{text}</p>{button}</article>'
    body+='<article id="merchandise"><h2>Merchandise</h2><p>Products are coming soon. Discover the Upliftment T-shirt concepts and Kings artwork as we build a made-to-order collection.</p><a class="text-link" href="/programs/">Preview the merchandise ↗</a></article></section><section class="section"><p class="eyebrow">OUR PARTNERS / COMING SOON</p><h2>Shared purpose.<br><em>Stronger connections.</em></h2><p>Corporate sponsors and charity partners will be featured here as partnerships are confirmed.</p><button class="button gold enquiry-open" data-enquiry="partners">Become a partner ↗</button></section>'
    shell('/contact/','Contact Kings of Kings | Events, Artists & Partnerships','Enquire about touring, live events, artist bookings, record releases, charities and sponsorship. Join Kings of Kings event updates and Top 15 chart news.',body)
    merch=intro('THE KINGS COLLECTION / COMING SOON','Wear the music.<br><em>Carry the culture.</em>','Preview the Upliftment collection. Products and online ordering are coming soon.')+f'<section class="section"><div class="merch-previews"><figure>{image("/assets/current/upliftment-shirts.webp","Upliftment black and white T-shirt front mockups")}<figcaption>Upliftment T-shirt concepts · product mockups</figcaption></figure><figure>{image("/assets/current/upliftment-shirts-back.webp","Kings of Kings T-shirt back mockups")}<figcaption>Kings of Kings back design · product mockups</figcaption></figure></div><h2>Made for<br><em>reggae lovers.</em></h2><p>We’re planning a made-to-order collection with fulfilment handled by a production partner. Designs, product options, prices and delivery details will be confirmed before the shop opens.</p><button class="button gold enquiry-open" data-enquiry="mailing-list">Tell me when the shop opens ↗</button></section>'
    shell('/programs/','Kings Merchandise | Upliftment T-Shirts Coming Soon','Preview Kings of Kings and Iley Dread Upliftment T-shirt mockups. Merchandise and online ordering are coming soon.',merch)
    contest=intro('SPECIAL PROMOTIONS','Upliftment.<br><em>Share the celebration.</em>','A giveaway to celebrate the January 5, 2027 album release.')+f'<section class="section album-spotlight"><div>{image("/assets/current/upliftment.webp","Iley Dread Upliftment album cover")}{image("/assets/current/upliftment-shirts.webp","Upliftment T-shirt prize mockup")}</div><div><p class="eyebrow">JANUARY 5, 2027 / PLANNED GIVEAWAY</p><h2>Three lucky<br>winners.</h2><p>Celebrate Upliftment with a chance to win an album copy and a T-shirt. Three winners are planned for this special promotion.</p><p class="label">ENTRIES OPEN SOON</p><p>Sign up for the Kings of Kings newsletter to receive an entry when registration opens. You must be 18 or older and agree that your name may be published online if you win. Void where prohibited. Winners will be notified by email. Entries close January 5, 2027 at 5:00 p.m. EST (Toronto time). Full rules will be available before registration opens.</p><button class="button gold enquiry-open" data-enquiry="giveaway">Newsletter & giveaway signup ↗</button><p class="small-note">Registration is not active in this preview. No entry is recorded until the live signup system is enabled.</p></div></section>'
    shell('/contests/','Upliftment Giveaway | January 5, 2027','Kings of Kings plans an Upliftment album and T-shirt giveaway for three winners to celebrate January 5, 2027. Entry details and official rules coming soon.',contest)
    chart=intro('KINGS OF KINGS / COMING SOON','The Top 15.<br><em>Feel what’s next.</em>','The Kings of Kings Top 15 Chart is coming soon.')+'<section class="section"><p>Join the notification list to hear when the chart launches.</p><button class="button gold enquiry-open" data-enquiry="top-15">Be the first to know ↗</button></section>'
    shell('/top-15/','Kings of Kings Top 15 Chart | Coming Soon','Join the notification list for the Kings of Kings Top 15 Chart. Coming soon.',chart)
